test_patch:
diff --git a/rust/fslc/tests/reviewgraphen_generated_calibration_07.rs b/rust/fslc/tests/reviewgraphen_generated_calibration_07.rs
new file mode 100644
--- /dev/null
+++ b/rust/fslc/tests/reviewgraphen_generated_calibration_07.rs
@@ -0,0 +1,20 @@
+// SPDX-License-Identifier: Apache-2.0
+
+const CLI_SOURCE: &str = include_str!("../src/main.rs");
+
+#[test]
+fn reviewgraphen_generated_regression() {
+    let start = CLI_SOURCE
+        .find("fn stable_kernel_projection(")
+        .expect("stable kernel projection");
+    let remainder = &CLI_SOURCE[start..];
+    let end = remainder
+        .find("fn raw_delivery_allowed(")
+        .expect("following function");
+    let projection = &remainder[..end];
+
+    assert!(
+        projection.lines().any(|line| line.trim() == "\"trans\","),
+        "stable kernel projection must retain transition-property identity"
+    );
+}
